# area: narrowing_user
# hypothesis: a generic TypeIs guard narrows attribute and literal-index subscript expressions in both branches, and a checker that drops member or subscript narrowing reports the declared union instead.
from typing import TypeIs, TypeVar, assert_type

T = TypeVar('T')


def is_kind(val: object, kind: type[T]) -> TypeIs[T]:
    return isinstance(val, kind)


class Box:
    def __init__(self, value: int | str) -> None:
        self.value = value

    def describe(self) -> str:
        if is_kind(self.value, str):
            assert_type(self.value, str)
            return self.value.upper()
        assert_type(self.value, int)
        return str(self.value + 1)


def first_kind(items: list[int | str]) -> str:
    if is_kind(items[0], str):
        assert_type(items[0], str)
        return items[0].upper()
    assert_type(items[0], int)
    return str(items[0] * 10)


print(Box(3).describe())
print(Box('ab').describe())
print(first_kind([5, 'x']))
print(first_kind(['q']))
